std::shared_timed_mutex mtx;

void access_resource() {
    using namespace std::chrono;
    milliseconds timeout(50);

    // Attempt shared lock with timeout
    bool locked = mtx.try_lock_shared_for(timeout);

    if (locked) {
        // Success: Perform read operation
        mtx.unlock_shared();
    } else {
        // Failure: Timeout elapsed
    }
}
